<script>(function(){document.querySelectorAll('.credential-form').forEach(function(form){form.querySelectorAll('.credential-clear').forEach(function(item){item.remove()});var row=form.closest('tr'),state=row&&row.querySelector('.credential-state');if(state&&!state.classList.contains('missing')){form.innerHTML='<div class="credential-actions" style="justify-content:center"><span class="credential-state"><i class="fa fa-lock"></i> 已配置，禁止再次编辑</span></div>';}})})();</script>
<script>(function(){var headers=document.querySelectorAll('.fashion-store-table thead th'),target=null;Array.prototype.forEach.call(headers,function(header){if(header.textContent.indexOf('XShoppy App API')!==-1){target=header;}});if(!target||document.getElementById('xshoppyCredentialGuideButton'))return;var button=document.createElement('button');button.type='button';button.id='xshoppyCredentialGuideButton';button.className='credential-example-button';button.setAttribute('data-toggle','modal');button.setAttribute('data-target','#xshoppyCredentialGuideModal');button.innerHTML='<i class="fa fa-picture-o"></i> 查看示例';target.appendChild(button);})();</script>
